import{_ as e}from"./chunks/more.BA9dr6o4.js";import{_ as t,c as r,o,a2 as i}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"その他の比較方法","description":"画像やアーカイブを比較し、比較結果を画像として書き出し、外観と言語を調整します。","frontmatter":{"title":"その他の比較方法","description":"画像やアーカイブを比較し、比較結果を画像として書き出し、外観と言語を調整します。"},"headers":[],"relativePath":"ja/guide/more.md","filePath":"ja/guide/more.md","lastUpdated":1794296122000}'),l={name:"ja/guide/more.md"};function s(n,a,d,h,p,c){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="その他の比較方法" tabindex="-1">その他の比較方法 <a class="header-anchor" href="#その他の比較方法" aria-label="Permalink to &quot;その他の比較方法&quot;">​</a></h1><p>テキストは話の半分にすぎません。qDiff は同じ「並べて比べる」考え方で、他の 種類のコンテンツも開けます。</p><img src="'+e+'" alt="2 枚の画像を並べて比較した画面" class="guide-shot"><h2 id="画像" tabindex="-1">画像 <a class="header-anchor" href="#画像" aria-label="Permalink to &quot;画像&quot;">​</a></h2><p>2 枚の画像を並べてじっくり比べたり、重ね合わせて違う場所を正確に確かめたり できます。デザインの改訂や、ほとんど同じに見える写真の確認に便利です。</p><h2 id="圧縮アーカイブ" tabindex="-1">圧縮アーカイブ <a class="header-anchor" href="#圧縮アーカイブ" aria-label="Permalink to &quot;圧縮アーカイブ&quot;">​</a></h2><p>.zip や .tar アーカイブは直接開いて、フォルダのように比較できます。解凍も、 後で一時ファイルを片付ける必要もありません。</p><h2 id="プレーンテキストではないファイル" tabindex="-1">プレーンテキストではないファイル <a class="header-anchor" href="#プレーンテキストではないファイル" aria-label="Permalink to &quot;プレーンテキストではないファイル&quot;">​</a></h2><p>2 つのファイルが同じに見えても動作が違うとき、qDiff はごく細かな違いまで 比較できます。テキスト表示では分からない差も見つけ出します。</p><h2 id="比較結果を画像として保存する" tabindex="-1">比較結果を画像として保存する <a class="header-anchor" href="#比較結果を画像として保存する" aria-label="Permalink to &quot;比較結果を画像として保存する&quot;">​</a></h2><p>変更を選んで、きれいな 2 段組みの画像として書き出せます。メッセージ、文書、 レビューにそのまま貼り付けられます。画像にマークは追加されません。</p><h2 id="自分好みに設定する" tabindex="-1">自分好みに設定する <a class="header-anchor" href="#自分好みに設定する" aria-label="Permalink to &quot;自分好みに設定する&quot;">​</a></h2><ul><li><strong>外観</strong> —— ライトとダーク。Mac の設定に従うか、手動で指定できます。</li><li><strong>言語</strong> —— 英語、簡体字中国語、繁体字中国語、日本語、ドイツ語、スペイン語、フランス語の 7 言語から選べます。</li><li><strong>フォントとショートカット</strong> —— 読みやすさを調整し、よく使う操作をキーボードで 行えます。</li><li><strong>最近の比較</strong> —— 昨日見た内容を、ウェルカム画面からすぐに開けます。</li></ul><p>以上の機能はすべて無料版に含まれています。</p><p>ご質問は？<a href="./faq.html">FAQ をご覧ください</a>。</p>',15)])])}const f=t(l,[["render",s]]);export{u as __pageData,f as default};
